# expected_conditional_age_at_length ----
## Setup ----
# 3 ages, 2 length bins and 1 year.
numbers_at_age <- matrix(c(100, 50, 25), nrow = 1)
age_to_length <- matrix(c(0.8, 0.2, 0.5, 0.5, 0.1, 0.9), 3, 2, byrow = TRUE)

## IO correctness ----
test_that("`expected_conditional_age_at_length()` works with correct inputs", {
  conditional_age_at_length <- FIMS:::expected_conditional_age_at_length(
    numbers_at_age, age_to_length,
    year = c(1, 1), length_bin = c(1, 2)
  )
  #' @description Test that `expected_conditional_age_at_length()` matches a hand calculation of P(age | length) for the first length bin.
  expect_equal(
    object = conditional_age_at_length[1, ],
    expected = c(80, 25, 2.5) / 107.5,
    tolerance = 1e-12
  )
  #' @description Test that `expected_conditional_age_at_length()` matches a hand calculation of P(age | length) for the second length bin.
  expect_equal(
    object = conditional_age_at_length[2, ],
    expected = c(20, 25, 22.5) / 67.5,
    tolerance = 1e-12
  )
  #' @description Test that each row of `expected_conditional_age_at_length()` sums to 1.
  expect_equal(
    object = rowSums(conditional_age_at_length),
    expected = c(1, 1)
  )

  # Law of total probability: averaging P(age | length) over the expected
  # length composition gives back the expected age composition.
  age_proportion <- numbers_at_age / sum(numbers_at_age)
  length_proportion <- FIMS:::evaluate_length_comp(
    age_proportion, age_to_length
  )[["proportion"]]
  #' @description Test that averaging `expected_conditional_age_at_length()` over the expected length composition from `evaluate_length_comp()` returns the expected age composition.
  expect_equal(
    object = as.vector(length_proportion %*% conditional_age_at_length),
    expected = as.vector(age_proportion),
    tolerance = 1e-12
  )
})

